Here are the commands to solve the task:

```cmd
mkdir calculator_project
mkdir calculator_project\components
mkdir calculator_project\components\arithmetic
mkdir calculator_project\components\calculator
mkdir calculator_project\bin

touch calculator_project\components\arithmetic\main.c
touch calculator_project\components\calculator\main.c
touch calculator_project\components\calculator\test.txt
touch calculator_project\components\calculator\testcases.txt

{write_to_file} calculator_project\components\arithmetic\main.c {content_start}
#include<stdio.h>
int add(int a, int b) {
    return a + b;
}
int subtract(int a, int b) {
    return a - b;
}
int multiply(int a, int b) {
    return a * b;
}
int divide(int a, int b) {
    if (b == 0) {
        printf("Error: Division by zero!\n");
        return -1;
    }
    return a / b;
}
{content_end}

{write_to_file} calculator_project\components\calculator\main.c {content_start}
#include<stdio.h>
#include<string.h>
char operation[5];
int x, y;
int result = 0;
{content_start}
int main() {
    printf("Calculator Program\n");
    printf("1. Arithmetic\n");
    printf("2. Calculator\n");
    printf("3. Exit\n");
    printf("Enter your choice: ");
    scanf("%d", &operation[0]);
    switch (operation[0]) {
        case '1':
            printf("Enter first number: ");
            scanf("%d", &x);
            printf("Enter second number: ");
            scanf("%d", &y);
            result = add(x, y);
            printf("Result: %d\n", result);
            break;
        case '2':
            printf("Enter operation (add, subtract, multiply, divide): ");
            scanf("%s", operation);
            switch (operation[0]) {
                case 'a':
                    printf("Enter first number: ");
                    scanf("%d", &x);
                    printf("Enter second number: ");
                    scanf("%d", &y);
                    result = divide(x, y);
                    printf("Result: %d\n", result);
                    break;
                case s':
                    printf("Enter first number: ");
                    scanf("%d", &x);
                    printf("Enter second number: ");
                    scanf("%d", &y);
                    result = multiply(x, y);
                    printf("Result: %d\n", result);
                    break;
                case m':
                    printf("Enter first number: ");
                    scanf("%d", &x);
                    printf("Enter second number: ");
                    scanf("%d", &y);
                    result = subtract(x, y);
                    printf("Result: %d\n", result);
                    break;
                case 'd':
                    printf("Enter first number: ");
                    scanf("%d", &x);
                    printf("Enter second number: ");
                    scanf("%d", &y);
                    result = add(x, y);
                    printf("Result: %d\n", result);
                    break;
            }
            break;
        case '3':
            printf("Exiting...\n");
            break;
        default:
            printf("Invalid choice!\n");
            break;
    }
    return 0;
}
{content_end}

